  1	import streamDeck from "@elgato/streamdeck";
  2	
  3	import { AutoRoll } from "./actions/autoroll.ts";
  4	import { Clock } from "./actions/clock.ts";
  5	import { Connect } from "./actions/connect.ts";
  6	import { Finish } from "./actions/finish.ts";
  7	import { Metric } from "./actions/metric.ts";
  8	import { Next } from "./actions/next.ts";
  9	import { Open } from "./actions/open.ts";
 10	import { Press } from "./actions/press.ts";
 11	import { Roll } from "./actions/roll.ts";
 12	import { pin, Run, runsForInspector } from "./actions/run.ts";
 13	import { Setup } from "./actions/setup.ts";
 14	import { Undo } from "./actions/undo.ts";
 15	import { profileFor } from "./profiles.ts";
 16	import { loadSession, normalizeBase, signIn, signOut, type Account } from "./session.ts";
 17	import { openWire } from "./socket.ts";
 18	import { makeStore } from "./store.ts";
 19	import { idleDeadline, type DeckState } from "./state.ts";
 20	
 21	/** Where Runlog lives when the streamer has not said otherwise. */
 22	const DEFAULT_API = "https://runlog.scrthq.com";
 23	
 24	/**
 25	 * What the plugin keeps between launches.
 26	 *
 27	 * The address and the pinned run, and nothing else: global settings are
 28	 * handed to the property inspector, which is a web view, so the session
 29	 * never comes near them. It lives in a file of the plugin's own.
 30	 */
 31	type Globals = { apiBase?: string; pinned?: string | null; switchProfiles?: boolean };
 32	
 33	let base = DEFAULT_API;
 34	
 35	/** Whether attaching to a run moves the deck to that run's profile. Unset is on. */
 36	let switchProfiles = true;
 37	
 38	/**
 39	 * Where Runlog is, for a key that has to name an address rather than
 40	 * press through the wire. The normalized global setting, so a deck
 41	 * pointed at a copy of the app opens that copy pages.
 42	 */
 43	export function apiBase(): string {
 44	  return base;
 45	}
 46	
 47	export const store = makeStore();
 48	export const wire = openWire((): Account => ({ apiBase: base }), store);
 49	
 50	/**
 51	 * Attaching moves the deck to the profile laid out for the run's pack.
 52	 *
 53	 * It is the one attach feedback that works on every model, a six-key Mini
 54	 * included, and it puts the pack's own moves under the streamer's hand the
 55	 * moment a run starts. A pack's profile is not installed until this asks
 56	 * for it, which is what keeps forty profiles out of a new install's list.
 57	 *
 58	 * On the first snapshot of an attach rather than on the attach itself: the
 59	 * pack's id travels with the snapshot, and the run's is not known until one
 60	 * lands. Once per attach after that, since a snapshot landing is not a
 61	 * reason to yank the deck away from wherever the streamer has gone since.
 62	 */
 63	let switchedFor: string | null = null;
 64	store.subscribe((s) => {
 65	  if (!s.attached) {
 66	    switchedFor = null;
 67	    return;
 68	  }
 69	  if (!switchProfiles || switchedFor === s.attached || !s.snapshot) return;
 70	  switchedFor = s.attached;
 71	  for (const d of streamDeck.devices) {
 72	    const name = profileFor(s.snapshot.run?.packId, d.type);
 73	    if (name) void streamDeck.profiles.switchToProfile(d.id, name).catch(() => {});
 74	  }
 75	});
 76	
 77	// The Run inspector's list is only as fresh as the last appear; a run
 78	// starting or ending while the picker is open moves it without the
 79	// streamer closing and reopening the page.
 80	let lastRuns: DeckState["runs"] | null = null;
 81	store.subscribe((s) => {
 82	  if (s.runs === lastRuns) return;
 83	  lastRuns = s.runs;
 84	  if (streamDeck.ui.action) void streamDeck.ui.sendToPropertyInspector({ t: "runs", runs: runsForInspector(s.runs), pinned: s.pinned });
 85	});
 86	
 87	/**
 88	 * Switching the deck on.
 89	 *
 90	 * The address is read again first, so the one the streamer last typed is the
 91	 * one dialed. Reconnecting through drops after that is the wire's own job.
 92	 */
 93	export function turnOn(): void {
 94	  if (store.state.on) return;
 95	  store.dispatch({ t: "on", on: true });
 96	  void (async () => {
 97	    await readGlobals();
 98	    streamDeck.logger.info("on: connecting");
 99	    wire.connect();
100	  })();
101	}
102	
103	/** Switching it off, by a press or - with `idle` - by the deck's own timer. */
104	export function turnOff(idle = false): void {
105	  wire.disconnect();
106	  store.dispatch({ t: "on", on: false, idle });
107	  streamDeck.logger.info(idle ? "off: idle for thirty minutes" : "off: by request");
108	}
109	
110	/** Tells whichever inspector is open where it is pointed and whether anyone is signed in. */
111	export async function sayWho(): Promise<void> {
112	  await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: loadSession() !== null, apiBase: base });
113	}
114	
115	function applyGlobals(g: Globals): void {
116	  base = normalizeBase(g.apiBase ?? "") || DEFAULT_API;
117	  // Unset is on: a deck that has never opened Connect's settings still
118	  // lands on the run's profile.
119	  switchProfiles = g.switchProfiles !== false;
120	  // Only on a change: this fires from the plugin's own write of a pin as
121	  // much as from another surface's, and a pin already applied locally
122	  // should not force the run's snapshot to reload for nothing.
123	  if (g.pinned !== undefined && g.pinned !== store.state.pinned) store.dispatch({ t: "pin", id: g.pinned });
124	}
125	
126	async function readGlobals(): Promise<void> {
127	  applyGlobals(await streamDeck.settings.getGlobalSettings<Globals>());
128	}
129	
130	// A deck holding no run for half an hour closes its own socket rather than
131	// sitting on one all night. A deck following a run never times out.
132	let idleSince: number | null = null;
133	let idleTimer: ReturnType<typeof setTimeout> | null = null;
134	store.subscribe((state) => {
135	  const now = Date.now();
136	  const deadline = idleDeadline(state, idleSince ?? now);
137	  if (deadline === null) {
138	    idleSince = null;
139	    if (idleTimer) clearTimeout(idleTimer);
140	    idleTimer = null;
141	    return;
142	  }
143	  if (idleTimer) return;
144	  idleSince = now;
145	  idleTimer = setTimeout(() => {
146	    idleTimer = null;
147	    turnOff(true);
148	  }, deadline - now);
149	});
150	
151	/**
152	 * The device flow's two lines, as the inspector needs them: the page and the code.
153	 *
154	 * `deviceFlow` writes for a terminal, two spaces and a label per line.
155	 * Exported so a test can hold this against the lines the flow actually
156	 * says - the inspector shows nothing at all if the two stop matching,
157	 * and nothing at all is a sign-in that looks like it hung.
158	 */
159	export function codeFromLines(): (line: string) => void {
160	  let code: string | null = null;
161	  let url: string | null = null;
162	  let sent = false;
163	  return (line) => {
164	    code = /^ {2}Code {2}(\S.*)$/.exec(line)?.[1]?.trim() ?? code;
165	    url = /^ {2}Open {2}(\S+)$/.exec(line)?.[1] ?? url;
166	    // Once. The flow keeps talking after those two lines - a blank, then
167	    // what a terminal should do while it waits - and every line after them
168	    // still has both halves in hand.
169	    if (code && url && !sent) {
170	      sent = true;
171	      void streamDeck.ui.sendToPropertyInspector({ t: "code", code, url });
172	    }
173	  };
174	}
175	
176	streamDeck.ui.onSendToPlugin<{ t?: string; id?: string | null }>(async (ev) => {
177	  switch (ev.payload?.t) {
178	    case "pin":
179	      await pin(ev.payload?.id ?? null);
180	      break;
181	    case "signin":
182	      try {
183	        streamDeck.logger.info("sign-in: starting the device flow");
184	        await signIn({ apiBase: base }, codeFromLines(), () => {});
185	        store.dispatch({ t: "session", state: "ok" });
186	        streamDeck.logger.info("sign-in: done");
187	        // Signed in is not connected: the streamer presses Connect.
188	        await streamDeck.ui.sendToPropertyInspector({ t: "who", name: "you", signedIn: true, apiBase: base });
189	      } catch (e) {
190	        // The reason goes back to the inspector, not only to the log: the
191	        // streamer is looking at the button they pressed, and a status line
192	        // that flips back to "Not signed in" tells them nothing.
193	        const error = e instanceof Error ? e.message : "unknown";
194	        streamDeck.logger.error(`sign-in: failed (${error})`);
195	        await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase: base, error });
196	      }
197	      break;
198	    case "signout":
199	      turnOff();
200	      signOut();
201	      store.dispatch({ t: "session", state: "none" });
202	      streamDeck.logger.info("signed out");
203	      await streamDeck.ui.sendToPropertyInspector({ t: "who", signedIn: false, apiBase: base });
204	      break;
205	    case "reconnect":
206	      turnOff();
207	      turnOn();
208	      break;
209	    default:
210	      break;
211	  }
212	});
213	
214	streamDeck.logger.setLevel("info");
215	streamDeck.settings.onDidReceiveGlobalSettings<Globals>((ev) => applyGlobals(ev.settings));
216	
217	// A flash lasts three seconds and nothing else clears it; the tick is what
218	// puts a refused key back to what it was saying.
219	setInterval(() => store.dispatch({ t: "tick" }), 1000);
220	
221	for (const a of [
222	  new Next(),
223	  new Press(),
224	  new Roll(),
225	  new Undo(),
226	  new Run(),
227	  new Metric(),
228	  new Connect(),
229	  new Setup(),
230	  new Open(),
231	  new Clock(),
232	  new AutoRoll(),
233	  new Finish(),
234	]) {
235	  streamDeck.actions.registerAction(a);
236	}
237	
238	void streamDeck.connect().then(async () => {
239	  // Launch is quiet: the settings, the session, and nothing else. No socket
240	  // and no token refresh until the streamer presses Connect.
241	  await readGlobals();
242	  const signedIn = loadSession() !== null;
243	  store.dispatch({ t: "session", state: signedIn ? "ok" : "none" });
244	  streamDeck.logger.info(`launched: ${signedIn ? "signed in" : "not signed in"}, not connected`);
245	});
246	/**
247	 * Which profile a run's pack is laid out in, and what each deck is called.
248	 *
249	 * Written by `design/profiles.mjs`: run `npm run profiles -w streamdeck`
250	 * and commit what moves. Editing it by hand renames a profile the plugin
251	 * asks for without renaming the file behind it, and the switch then does
252	 * nothing at all.
253	 */
254	
255	/** The slug of the profile laid out for each pack the plugin ships. */
256	export const PACK_PROFILES: Record<string, string> = {
257	  "com.scrthq.runlog.long-kiln": "demo",
258	  "com.scrthq.runlog.elden-ring-tarnishedtool": "elden-ring",
259	  "com.scrthq.runlog.forfeits": "forfeits",
260	  "com.scrthq.runlog.ladder-work": "ladder-work",
261	  "com.scrthq.runlog.practice-room": "practice-room",
262	  "com.scrthq.runlog.rocket-league-ladder": "rocket-league-ladder",
263	  "com.scrthq.runlog.rocket-league-showdown": "rocket-league-showdown",
264	  "com.scrthq.runlog.run-of-show": "run-of-show",
265	  "com.scrthq.runlog.soundclash": "soundclash",
266	  "com.scrthq.runlog.twenty-five": "twenty-five",
267	};
268	
269	/** What a profile name calls each deck, by the SDK's `DeviceType`. */
270	export const DEVICE_PROFILES: Record<number, string> = {
271	  2: "xl",
272	  0: "sd",
273	  1: "mini",
274	  7: "plus",
275	};
276	
277	/** The layout a run gets where its pack ships none, which is every Marketplace pack. */
278	export const GENERIC_PROFILE = "runlog";
279	
280	/**
281	 * The profile to put a deck on for a run of this pack.
282	 *
283	 * `null` for a deck nothing here is laid out for - a Pedal, a Neo - which is
284	 * a deck to leave alone rather than one to push the generic layout onto.
285	 */
286	export function profileFor(packId: string | undefined, device: number): string | null {
287	  const deck = DEVICE_PROFILES[device];
288	  if (deck === undefined) return null;
289	  const slug = (packId === undefined ? undefined : PACK_PROFILES[packId]) ?? GENERIC_PROFILE;
290	  return `profiles/${slug}-${deck}`;
291	}
292	/**
293	 * Each action's drawing, as markup to inline in a key face.
294	 *
295	 * Written by `npm run icons -w streamdeck` from `design/actions/*.svg`.
296	 * Edit the drawings, not this file. The viewBox they are drawn in is 144
297	 * square, which is what `face.ts` scales them down from.
298	 */
299	export const GLYPHS: Record<string, string> = {
300	  autoroll:
301	    '<rect x="18" y="62" width="52" height="52" rx="12" fill="none" stroke="#ffffff" stroke-width="11"/> <circle cx="44" cy="88" r="8" fill="#ffffff"/> <rect x="78" y="62" width="52" height="52" rx="12" fill="none" stroke="#ffffff" stroke-width="11"/> <circle cx="94" cy="78" r="7" fill="#ffffff"/> <circle cx="114" cy="98" r="7" fill="#ffffff"/> <path d="M26 46 A60 60 0 0 1 118 46" fill="none" stroke="#ffffff" stroke-width="11" stroke-linecap="round"/> <path d="M104 32 H132 L118 60 Z" fill="#ffffff"/>',
