  1	import streamDeck, {
  2	  SingletonAction,
  3	  type DialAction,
  4	  type DidReceiveSettingsEvent,
  5	  type FeedbackPayload,
  6	  type KeyAction,
  7	  type WillAppearEvent,
  8	  type WillDisappearEvent,
  9	} from "@elgato/streamdeck";
 10	
 11	import { faceImage } from "../face.ts";
 12	import { GLYPHS } from "../glyphs.ts";
 13	import { sayWho, store, wire } from "../plugin.ts";
 14	import type { DeckState, Face } from "../state.ts";
 15	
 16	/**
 17	 * The JSON shape Stream Deck persists, mirrored rather than imported.
 18	 *
 19	 * `SingletonAction` constrains its settings to `@elgato/utils`' `JsonObject`,
 20	 * which `@elgato/streamdeck` does not re-export; this is the same type,
 21	 * structurally, without depending on a package the plugin does not declare.
 22	 */
 23	type JsonPrimitive = boolean | number | string | null | undefined;
 24	type JsonValue = JsonObject | JsonPrimitive | JsonValue[];
 25	export type JsonObject = { [key: string]: JsonValue };
 26	
 27	/** How long a press waits for the server's verdict before giving up on it. */
 28	const VERDICT_MS = 5000;
 29	
 30	/** How long a key is held before it counts as a hold rather than a tap. */
 31	export const HOLD_MS = 600;
 32	
 33	/** How long the Finish key is held, which is longer because the run ends. */
 34	export const FINISH_HOLD_MS = 1500;
 35	
 36	/**
 37	 * A key that tells a hold from a tap.
 38	 *
 39	 * The software sends a key down and a key up and nothing in between, so
 40	 * the length of a press is the plugin's own arithmetic: `down` on the way
 41	 * down, `up` on the way back for how long it was. A key that times a press
 42	 * this way has to act on the way up rather than the way down, which is the
 43	 * one thing that makes it feel different from every other key on the deck.
 44	 */
 45	export class HoldTimer {
 46	  private at = new Map<string, number>();
 47	
 48	  down(id: string, now = Date.now()): void {
 49	    this.at.set(id, now);
 50	  }
 51	
 52	  /** How long this key was held, or null where the press did not start here - a redraw mid-press, a plugin restart. */
 53	  up(id: string, now = Date.now()): number | null {
 54	    const at = this.at.get(id);
 55	    if (at === undefined) return null;
 56	    this.at.delete(id);
 57	    return now - at;
 58	  }
 59	}
 60	
 61	/** Either kind of placed action - a key on the grid, or a dial on a Stream Deck +. */
 62	export type Placed<S extends JsonObject> = DialAction<S> | KeyAction<S>;
 63	
 64	/**
 65	 * What every Runlog action has in common: one state, one wire, one drawing.
 66	 *
 67	 * A subclass says only what its face is. Redrawing is a subscription to the
 68	 * store held while any instance of the action is placed, so a key follows
 69	 * the run without knowing anything about the socket behind it.
 70	 */
 71	export abstract class RunlogAction<S extends JsonObject = JsonObject> extends SingletonAction<S> {
 72	  private unsub: (() => void) | null = null;
 73	  /** What each placement last said, so a change is logged once and a redraw that says the same thing is not. */
 74	  private said = new Map<string, string>();
 75	
 76	  /** What this action says, given everything the plugin knows. */
 77	  abstract face(state: DeckState, settings: S, now: number): Face;
 78	
 79	  /**
 80	   * The drawing this action wears in the corner of its keys.
 81	   *
 82	   * By the last word of the UUID, which is the name its SVG is filed under
 83	   * in `design/actions`: one home for the pairing, and a new action gets
 84	   * its glyph by being named after its drawing rather than by a table.
 85	   */
 86	  private glyph(): string | undefined {
 87	    return GLYPHS[this.manifestId?.split(".").pop() ?? ""];
 88	  }
 89	
 90	  override async onWillAppear(ev: WillAppearEvent<S>): Promise<void> {
 91	    this.unsub ??= store.subscribe(() => this.redrawAll());
 92	    const face = this.face(store.state, ev.payload.settings, Date.now());
 93	    // What a key came up saying, which is the only way to read the deck from
 94	    // a log. Once per placement, not once per redraw.
 95	    streamDeck.logger.info(`appeared: ${this.manifestId ?? "?"} says "${face.title}"`);
 96	    await this.draw(ev.action, ev.payload.settings);
 97	  }
 98	
 99	  override onWillDisappear(_ev: WillDisappearEvent<S>): void {
100	    if (this.actions.length > 0) return;
101	    this.unsub?.();
102	    this.unsub = null;
103	  }
104	
105	  /** A setting changed in the inspector redraws the key it was changed for. */
106	  override async onDidReceiveSettings(ev: DidReceiveSettingsEvent<S>): Promise<void> {
107	    await this.draw(ev.action, ev.payload.settings);
108	  }
109	
110	  /** Every inspector carries the account block, so every inspector is told who is signed in. */
111	  override async onPropertyInspectorDidAppear(): Promise<void> {
112	    await sayWho();
113	  }
114	
115	  protected async draw(action: Placed<S>, settings: S): Promise<void> {
116	    // The whole redraw is inside the try, the face included: a state a
117	    // face was not written for, an image the software will not take, a
118	    // dial that went away mid-write. The SDK's uncaughtException handler
119	    // is registered `once`, so the second throw anywhere in here would be
120	    // the plugin's last.
121	    try {
122	      const face = this.face(store.state, settings, Date.now());
123	      if (this.said.get(action.id) !== face.title) {
124	        this.said.set(action.id, face.title);
125	        streamDeck.logger.info(
126	          `${this.manifestId ?? "?"} ${action.id} (${action.controllerType}) now says "${face.title}" for ${JSON.stringify(settings)}`,
127	        );
128	      }
129	      if (action.isKey()) {
130	        await action.setImage(faceImage(face, this.glyph()));
131	        await action.setTitle("");
132	      } else if (action.isDial()) {
133	        // The `$B1` layout's progress bar is the `indicator` key; it only
134	        // has something to show for a running timer's fraction, controller
135	        // ruling 4 - anything else leaves it out rather than drawing an
136	        // empty bar.
137	        const feedback: FeedbackPayload = { title: face.when ?? "", value: face.title };
138	        if (face.fraction !== undefined) feedback.indicator = { value: Math.round(face.fraction * 100) };
139	        await action.setFeedback(feedback);
140	      }
141	    } catch (error) {
142	      // The software answers nothing on a bad image; a throw here is the
143	      // only word of it there is, and it is worth a line in the log.
144	      streamDeck.logger.error(`could not draw ${action.id}: ${String(error)}`);
145	    }
146	  }
147	
148	  private redrawAll(): void {
149	    // The settings read can reject too, and a rejection with nothing on it
150	    // is an unhandled one.
151	    for (const a of this.actions)
152	      void a
153	        .getSettings<S>()
154	        .then((s) => this.draw(a, s))
155	        .catch((error) => streamDeck.logger.error(`could not redraw ${a.id}: ${String(error)}`));
156	  }
157	
158	  /**
159	   * A press, with the flash the server's answer will turn into.
160	   *
161	   * The wait is bounded two ways, because a verdict that never comes would
162	   * otherwise leave a listener on the store for the life of the plugin: the
163	   * deck going off ends it silently, and a press still unanswered after
164	   * {@link VERDICT_MS} ends it with the alert - a press that vanished should
165	   * say so rather than nothing.
166	   */
167	  protected async send(action: Placed<S>, p: Parameters<typeof wire.press>[0]): Promise<void> {
168	    const ref = wire.press(p);
169	    if (!ref) {
170	      await action.showAlert();
171	      return;
172	    }
173	    let off: (() => void) | null = null;
174	    let timer: ReturnType<typeof setTimeout> | null = null;
175	    const stop = (): boolean => {
176	      if (off === null) return false;
177	      if (timer) clearTimeout(timer);
178	      off();
179	      off = null;
180	      return true;
181	    };
