    27	  /** The tallies and the dials, as the Trackers panel lists them. */
    28	  trackers: Array<{ id: string; kind: "counter" | "resource"; label: string; value: number; max: number | null }>;
    29	  /** The clock the page's Pause, Resume and Stop act on, where one is ticking. */
