    60	   * Handed in rather than worked out here, for the reason the trackers are:
    61	   * naming a trigger takes the pack, and this function is given what is on
    62	   * offer rather than the pack to read it from.
    63	   */
    64	  due: Array<{ id: string; label: string; kind: "threshold" | "global" }>;
    65	  /** What the run would suggest for a subject, where it suggests anything. */
    66	  suggestions: string[];
    67	  /** What the page's between-units button says, or null when the run is not between units. */
    68	  between: string | null;
    69	  /**
    70	   * What the step's own button says once every box is ticked, or null
    71	   * where the step has no list. The preset presses that button, so it is
    72	   * offered in the words the page uses for it.
    73	   */
    74	  finishLabel: string | null;
    75	  /**
    76	   * The setups this run could hand out, in the words the picker uses.
    77	   *
    78	   * Worked out by the page rather than here: a setup is written against
    79	   * the tool a run is talking to, and finding those means reading the
    80	   * shipped profiles and the shelf, neither of which this function has.
    81	   */
    82	  setups: Array<{ id: string; title: string }>;
    83	  /**
    84	   * Every tally and every dial the run keeps, worked out by the page for
    85	   * the reason the setups are: which of them the page draws depends on the
    86	   * pack and on who is at the table, and the panel that draws them is the
    87	   * one home for that.
    88	   */
    89	  trackers: Offer["trackers"];
    90	  /** The clock the page's own buttons act on, or null while none is. */
    91	  clock: Offer["clock"];
    92	  /** Whether this device is throwing the dice for the player. */
    93	  autoRoll: boolean;
    94	  /** What the page's Finish button says, where the page is showing one. */
    95	  ending: Offer["ending"];
    96	}
    97	
    98	/**
    99	 * Steps a key can answer with one press, because they ask nothing first.
   100	 *
   101	 * A step that closes the unit is not listed here: it is routed by
   102	 * `closesUnit` below, the same way whichever kind it is, rather than by
   103	 * its own kind.
   104	 */
   105	const PRESSABLE: Record<string, "roll" | "carry-on" | "close" | "enter"> = {
   106	  rollTable: "roll",
   107	};
   108	
   109	/** Steps that take something typed, and the preset that covers each. */
   110	const TYPED = new Set(["declareSubject"]);
   111	
   112	export function offerOf(input: OfferInput): Offer {
   113	  const moves = input.moves;
   114	  const undo = input.canUndo && input.lastResult ? { what: input.lastResult } : null;
   115	  const bare = {
   116	    seq: input.seq,
   117	    moves,
   118	    undo,
   119	    presets: [] as Offer["presets"],
   120	    setups: input.setups,
   121	    trackers: input.trackers,
   122	    clock: input.clock,
   123	    autoRoll: input.autoRoll,
   124	    ending: input.ending,
   125	  };
   126	
   127	  // A run nobody is playing -- not started, read-only, ended -- offers
   128	  // nothing at all, moves and undo included. They used to ride out on
   129	  // `bare`, and `takePress` reads only those two fields when it takes a
   130	  // move or an undo, so a deck could move a run the page itself would not
   131	  // let anyone touch. The setups go with them: what a finished run was
   132	  // played under is a record of what happened, and a key that could
   133	  // rewrite it from another room is worse than no key.
   134	  //
   135	  // The dials, the clock, the dice setting and the ending are held back for
   136	  // the same reason, and held back rather than merely refused: a key face
   137	  // drawn from an offer should go dim on a run nobody is playing rather
   138	  // than show a tally somebody can press and be told no.
   139	  if (!input.live)
   140	    return {
   141	      ...bare,
   142	      moves: [],
   143	      undo: null,
   144	      setups: [],
   145	      trackers: [],
   146	      clock: null,
   147	      autoRoll: false,
   148	      ending: null,
   149	      primary: null,
   150	      needsPage: "Open the run on the page",
   151	    };
   152	
   153	  // The receipts of the step's own throws sit on the page, waiting to be
   154	  // read, before anything about the step itself -- what it is, whether it
   155	  // closes the unit -- comes into it. No presets: the checklist and the
   156	  // between-units button are both still behind this same screen.
   157	  if (input.receipts) return { ...bare, primary: { id: "carry-on", label: "Carry on", kind: "receipt" }, needsPage: null };
   158	
   159	  // What the game is owed is the press, ahead of anything that would carry
   160	  // the run forward. A counter threshold left pending rode into the next
   161	  // scene in a live run, out of the page's own closing card and out of a
   162	  // deck's Next, because neither door counted it. So the Next key offers
   163	  // the panel's own button rather than going dim: the one press that
   164	  // settles it is the one on the key. Moves, undo and the dials stay on
   165	  // offer, the way the page leaves them on screen beside it.
   166	  //
   167	  // Settled only, so a throw already asked for is answered first, by the
   168	  // roll branch further down. Firing a trigger begins a block of its own,
   169	  // and `begin` writes over whatever was pending: offered mid-throw, this
   170	  // press would throw the run's own dice request away.
   171	  if (input.settled && input.due.length > 0) {
   172	    const first = input.due[0]!;
   173	    return { ...bare, primary: { id: "owed", label: first.label, kind: first.kind }, needsPage: null };
   174	  }
   175	
   176	  // What the player owes stops the same doors, checked here rather than
   177	  // after the step's own kind: entering the next unit carries the debt
   178	  // into it, and the between-units button below used to walk straight
   179	  // past this. A step still waiting on dice is left to the branch that
   180	  // handles it -- nobody is being asked to judge anything mid-throw --
   181	  // and a typed step keeps its preset, which answers the step rather than
   182	  // moving the run on.
   183	  if (input.owed > 0 && input.settled && !(input.step && TYPED.has(input.step.kind)))
   184	    return { ...bare, primary: null, needsPage: "Something is owed; settle it on the page" };
   185	
   186	  if (!input.step) {
   187	    if (input.between) return { ...bare, primary: { id: "enter", label: input.between, kind: "between" }, needsPage: null };
   188	    return { ...bare, primary: null, needsPage: null };
   189	  }
   190	
   191	  const step = input.step;
   192	  const kind = step.kind;
   193	  const label = input.stepLabel ?? "";
   194	
   195	  // An unsettled step is still being asked something, the same reasoning
   196	  // `closesTheUnit` uses to refuse an unsettled unit: it is not yet a bare
   197	  // press for a key to make. A pending roll is the one exception: nobody is
   198	  // being asked to judge anything, only to throw dice, and a deck can throw
   199	  // them the same way the page's own "Roll for me" does.
   200	  if (!input.settled) {
   201	    if (input.request?.kind === "roll")
   202	      return { ...bare, primary: { id: "roll", label: input.request.label, kind: "rollTable" }, needsPage: null };
   203	    return { ...bare, primary: null, needsPage: `${label} on the page` };
   204	  }
   205	
   206	  if (TYPED.has(kind))
   207	    return {
   208	      ...bare,
   209	      primary: null,
   210	      needsPage: `${label} on the page`,
   211	      presets: [{ kind, label, ...(input.suggestions.length > 0 ? { suggestions: input.suggestions } : {}) }],
   212	    };
   213	
   214	  /*
   215	   * Ticking the whole list and pressing the step's own button, for a key
   216	   * the streamer put there themselves.
   217	   *
   218	   * A preset, never the primary: `needsPage` stays, so the follow key goes
   219	   * on saying the list is on the page. Pressing this one skips the reading,
   220	   * which is a decision, and `handsFree.ts` gives the rule -- a decision is
   221	   * skipped only where somebody chose to skip it.
   222	   *
   223	   * The count is what the step waits for, which is its points less the
   224	   * optional ones. Not less the ones with nothing to show: that needs the
   225	   * log and the pack, and this says what is on offer from the step alone.
   226	   */
   227	  const list = checklistOf(step);
   228	  const ticking: Offer["presets"] =
   229	    list.length > 0 && input.finishLabel
   230	      ? [
   231	          {
   232	            kind: "checklist",
   233	            label: `Tick everything and ${input.finishLabel}`,
   234	            items: list.map(pointOf).filter((p) => !p.optional).length,
   235	          },
   236	        ]
   237	      : [];
   238	
   239	  // A step that closes the unit goes to the page's closing card, whichever
   240	  // kind it is underneath: a finalizeUnit, or a manual step marked
   241	  // closesUnit. Its own confirmation or checklist is the same kind of ask
   242	  // as any other and sends it back to the page; empty, it is the one
   243	  // press that writes the close, not a step's own carry-on.
   244	  if (closesUnit(step)) {
   245	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
   246	    return { ...bare, primary: { id: "close", label, kind: step.kind }, needsPage: null };
   247	  }
   248	
   249	  // A manual step that does not close the unit asks nothing on its own; it
   250	  // only asks something when it carries a checklist to confirm. Empty, it
   251	  // is as bare a press as a roll.
   252	  if (step.kind === "manual") {
   253	    if (list.length > 0) return { ...bare, primary: null, needsPage: `${label} on the page`, presets: ticking };
   254	    return { ...bare, primary: { id: "carry-on", label, kind }, needsPage: null };
   255	  }
   256	
   257	  const id = PRESSABLE[kind];
   258	  if (!id) return { ...bare, primary: null, needsPage: `${label} on the page` };
   259	  return { ...bare, primary: { id, label, kind }, needsPage: null };
   260	}

