  5	 *
  6	 * SVG, because it needs no rasterizer and no native module in a package
  7	 * the Marketplace installs; base64, because Stream Deck 7.5 on Windows
  8	 * rejects a raw SVG string despite the documentation. 144 square is the
  9	 * @2x size; the software scales it to any key.
 10	 *
 11	 * The palette is the app's own: celadon for a key that moves the run,
 12	 * kiln for a refusal and for undo, the muted ink for a key with nothing
 13	 * to do. System sans, since a font in an SVG would have to travel as
 14	 * base64 on every redraw.
 15	 *
 16	 * The grounds carry the family, because an edge 3px wide is not enough to
 17	 * tell six kinds of key apart across a deck at arm's length: celadon-tinted
 18	 * where the key moves the run, kiln-tinted for undo and for a refusal,
 19	 * neutral and a shade lighter for the furniture, near-black under a readout
 20	 * so the number floats. Every ink clears 4.5:1 on its own ground and every
 21	 * `when` line clears 3:1, which `face.test.ts` checks rather than trusts.
 22	 *
 23	 * `stroke` is the frame's width, and `quiet` the color of the `when` line
 24	 * and the corner glyph where the edge is too dark to read them in - a
 25	 * readout, the furniture, and a key with nothing to do, whose frames are
 26	 * hairlines and near-grounds rather than accents.
 27	 */
 28	const TONE: Record<Tone, { ground: string; ink: string; edge: string; stroke?: number; quiet?: string }> = {
 29	  live: { ground: "#243d31", ink: "#e7eae6", edge: "#8cc3a6" },
 30	  dim: { ground: "#1b201d", ink: "#8d958f", edge: "#2f3733", quiet: "#8d958f" },
 31	  refuse: { ground: "#33211a", ink: "#e7eae6", edge: "#dd8f63" },
 32	  undo: { ground: "#3a2a1f", ink: "#e7eae6", edge: "#dd8f63" },
 33	  deck: { ground: "#262b28", ink: "#e7eae6", edge: "#2f3733", quiet: "#8d958f" },
 34	  readout: { ground: "#121413", ink: "#e7eae6", edge: "#2f3733", stroke: 1, quiet: "#8d958f" },
 35	};
 36	
 37	const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
 38	
 39	/**
 40	 * Glyph widths in em for the system sans at weight 600 - Segoe UI Semibold
 41	 * on Windows, and near enough everywhere else. Counting characters was
 42	 * pessimistic: "connected" is nine narrow letters and fits at 26, but a
 43	 * count of ten sends it to 22. So the face measures instead, in classes
 44	 * coarse enough to read and close enough that the rendered ink stays
 45	 * inside the frame.
 46	 */
 47	const EM: Record<string, number> = {};
 48	for (const c of "ijl'.,:;!| ") EM[c] = 0.28;
 49	for (const c of "ftrI") EM[c] = 0.36;
 50	for (const c of "mw") EM[c] = 0.85;
 51	for (const c of "MW") EM[c] = 0.92;
 52	EM["…"] = 0.9;
 53	
 54	function em(ch: string): number {
 55	  const known = EM[ch];
 56	  if (known !== undefined) return known;
 57	  if (/[0-9a-z]/.test(ch)) return 0.55;
 58	  if (/[A-Z]/.test(ch)) return 0.68;
 59	  return 0.6;
 60	}
 61	
 62	/** How wide a line of text draws, in px, at this font size. */
 63	export function measure(text: string, size: number): number {
 64	  let w = 0;
 65	  for (const ch of text) w += em(ch);
 66	  return w * size;
 67	}
 68	
 69	/**
 70	 * The frame's usable width. 144 less 8 either side: the stroke is 3px wide
 71	 * centered at x=3, so 8 leaves 5px of clear ground inside it. Text is
 72	 * centered on 72, so a line no wider than this never reaches x=8 or x=136.
 73	 */
 74	const LINE = 144 - 2 * 8;
 75	const MAX_LINES = 3;
 76	
 77	/**
 78	 * The `when` line's own type: 16px monospace, a flat 0.6em per glyph rather
 79	 * than the title's per-glyph measurement. 128px at 16px holds 13 characters
 80	 * (128 / (16 * 0.6) = 13.33); a fourteenth never fits. 18px held only
 81	 * eleven, which cut "press Connect" - the one instruction on the key that
 82	 * has to be read whole - down to "press Conne…".
 83	 */
 84	const WHEN_SIZE = 16;
 85	const WHEN_MAX = 13;
 86	
 87	/**
 88	 * Fit `when` to `WHEN_MAX` characters. A word boundary that still leaves at
 89	 * least six characters reads better than a stub, so that is tried first;
 90	 * otherwise the cut falls back to characters. Either way an "…" marks what
 91	 * was cut, and nothing kept ever runs past `WHEN_MAX`.
 92	 */
 93	function ellipsizeWhen(text: string): string {
 94	  if (text.length <= WHEN_MAX) return text;
 95	  let cut = "";
 96	  for (const word of text.split(" ")) {
 97	    const next = cut ? `${cut} ${word}` : word;
 98	    if (next.length > WHEN_MAX) break;
 99	    cut = next;
100	  }
101	  if (cut.length < 6) cut = text.slice(0, WHEN_MAX);
102	  return `${cut}…`;
103	}
104	
105	/**
106	 * Greedy word wrap by measured width: pack words onto a line up to `width`
107	 * px at `size`, at most `lines` lines. A word too wide for a line of its
108	 * own is broken by characters and carries on below. The last line gets an
109	 * ellipsis if any text was left over.
110	 */
111	/**
112	 * The longest head of a hyphenated word that still fits, hyphen included,
113	 * or nothing where the word has no hyphen with anything in front of it.
114	 */
115	function hyphenated(word: string, size: number, width: number): string {
116	  let cut = "";
117	  for (let i = 1; i < word.length - 1; i++) {
118	    if (word[i] !== "-") continue;
119	    const head = word.slice(0, i + 1);
120	    if (measure(head, size) > width) break;
121	    cut = head;
122	  }
123	  return cut;
124	}
125	
126	export function wrap(text: string, size: number, width = LINE, lines = MAX_LINES): string[] {
127	  const words = text.split(/\s+/).filter(Boolean);
128	  const out: string[] = [];
129	  let i = 0;
130	  while (i < words.length && out.length < lines) {
131	    const word = words[i]!;
132	    if (measure(word, size) > width) {
133	      // A hyphen is already a break somebody wrote into the word, so it is
134	      // the one to use: "Bare-handed" reads as "Bare-" and "handed", not
135	      // as "Bare-hande" and "d". The hyphen stays on the line it ends.
136	      let cut = hyphenated(word, size, width);
137	      if (cut === "") {
138	        for (const ch of word) {
139	          if (measure(cut + ch, size) > width) break;
140	          cut += ch;
141	        }
142	      }
143	      // One glyph always goes, or a face narrower than its own type would
144	      // loop here forever.
145	      if (cut === "") cut = [...word][0]!;
146	      out.push(cut);
147	      words[i] = word.slice(cut.length);
148	      continue;
149	    }
150	    let line = word;
151	    i++;
152	    while (i < words.length && measure(line + " " + words[i], size) <= width) {
153	      line += " " + words[i];
154	      i++;
155	    }
156	    out.push(line);
157	  }
158	  if (i < words.length && out.length > 0) {
159	    let last = out[out.length - 1]!;
160	    while (last.length > 0 && measure(last + "…", size) > width) last = last.slice(0, -1);
161	    out[out.length - 1] = last + "…";
162	  }
163	  return out;
164	}
165	
166	/**
167	 * The type scale, biggest first. A title takes the first step that keeps
168	 * every word whole in the room it has; one too long for the last step is
169	 * wrapped to it anyway and ellipsized rather than drawn over the frame.
170	 */
171	const SCALE = [40, 34, 30, 26, 22] as const;
172	
173	/** Baseline to baseline, as a multiple of the size. */
174	const LEADING = 1.15;
175	
176	/**
177	 * The box the title is centered in: top, bottom, and so the room between.
178	 *
179	 * Height used to be nobody's business, since three lines at any size were
180	 * assumed to fit. They do not: "Give Great Runes" came out three lines of
181	 * 40px and sat on top of the `when` line under it. So the box shrinks for
182	 * whatever else the key is wearing. A glyph holds the top 36px (8px in,
183	 * 28px square); a `when` line holds everything below 100, which leaves its
184	 * 16px band at y=126 clear; with neither, the title has 18 to 126 and sits
185	 * centered on the key the way it always did.
186	 */
187	function box(when: boolean, glyph: boolean): { top: number; bottom: number } {
188	  return { top: glyph ? 36 : when ? 20 : 18, bottom: when ? 100 : glyph ? 116 : 126 };
189	}
190	
191	/**
192	 * How many lines of this size the room holds, never more than `MAX_LINES`
193	 * and never fewer than one: a key with a glyph and a `when` line has room
194	 * for two lines of 26, and drawing a third would put it through the band
195	 * below. One line always draws, even where it overhangs, because a key with
196	 * nothing on it says less than a key with a cut title.
197	 */
198	function roomFor(size: number, room: number): number {
199	  return Math.max(1, Math.min(MAX_LINES, Math.floor(room / (size * LEADING))));
200	}
201	
202	/** Whether wrapping at this size keeps every word of the phrase. */
203	function whole(text: string, size: number, lines: number): boolean {
204	  return wrap(text, size, LINE, lines).join(" ") === text.split(/\s+/).filter(Boolean).join(" ");
205	}
206	
207	/**
208	 * The lines, the size, and where the middle of the first line sits. The
209	 * size is the largest whose lines fit the room as well as the width.
210	 */
211	function typeset(text: string, has: { when?: boolean; glyph?: boolean } = {}): { lines: string[]; size: number; top: number } {
212	  const { top, bottom } = box(has.when === true, has.glyph === true);
213	  const room = bottom - top;
214	  const size = SCALE.find((s) => whole(text, s, roomFor(s, room))) ?? SCALE[SCALE.length - 1]!;
215	  const lines = wrap(text, size, LINE, roomFor(size, room));
216	  return { lines, size, top: (top + bottom) / 2 - ((lines.length - 1) * size * LEADING) / 2 };
217	}
218	
219	/**
220	 * The corner glyph: 28px square, 8px in from the top and the left.
221	 *
222	 * The action's own drawing, so a key says which key it is while the title
223	 * says what it would do. The drawings are 144 square (`design/actions`),
224	 * so the scale is 28/144; they are drawn in white, and the white is
225	 * swapped for the tone's quiet color the way `design/export.mjs` swaps it
226	 * for the key images.
227	 *
228	 * 18px at 70% was a smudge on a deck across the room. 28px at 85% is a
229	 * mark you can name at arm's length and still not read before the title,
230	 * and the title now starts below it rather than behind it.
231	 */
232	const GLYPH_PX = 28;
233	const GLYPH_AT = 8;
234	
235	function corner(glyph: string, color: string): string {
236	  const scale = (GLYPH_PX / 144).toFixed(5);
237	  return `<g transform="translate(${GLYPH_AT} ${GLYPH_AT}) scale(${scale})" opacity="0.85">${glyph.replaceAll("#ffffff", color)}</g>`;
238	}
239	
240	export function faceImage(face: Face, glyph?: string): string {
241	  const t = TONE[face.tone];
242	  const quiet = t.quiet ?? t.edge;
243	  const { lines, size, top } = typeset(face.title, { when: face.when !== undefined, glyph: glyph !== undefined });
244	  // One positioned <text> per line, baseline given outright: the software
245	  // draws SVG with a renderer that honors x and y on a text element and
246	  // little else - a tspan with its own position, or a dominant-baseline,
247	  // left every title off the key while the small line beneath it showed.
248	  // 0.36em is where the middle of a semibold sans sits above its baseline.
249	  const spans = lines
250	    .map(
251	      (l, i) =>
252	        `<text class="t" x="72" y="${(top + i * size * LEADING + size * 0.36).toFixed(1)}" text-anchor="middle" font-size="${size}" font-weight="600" fill="${t.ink}" font-family="Segoe UI, Helvetica Neue, Helvetica, Arial, sans-serif">${esc(l)}</text>`,
253	    )
254	    .join("");
255	  const when = face.when
256	    ? `<text x="72" y="126" text-anchor="middle" font-size="${WHEN_SIZE}" fill="${quiet}" font-family="ui-monospace, Menlo, Consolas, monospace">${esc(ellipsizeWhen(face.when))}</text>`
257	    : "";
258	  const svg =
259	    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 144 144">` +
260	    // The full label, unwrapped, so a tooltip (or a test) sees the whole
261	    // thing even when the drawn lines above cut it short.
262	    `<title>${esc(face.title)}</title>` +
263	    `<rect width="144" height="144" rx="14" fill="${t.ground}"/>` +
264	    `<rect x="3" y="3" width="138" height="138" rx="12" fill="none" stroke="${t.edge}" stroke-width="${t.stroke ?? 3}"/>` +
265	    (glyph ? corner(glyph, quiet) : "") +
266	    spans +
267	    when +
268	    `</svg>`;
269	  return `data:image/svg+xml;base64,${Buffer.from(svg, "utf8").toString("base64")}`;
270	}

