     1	import { execFileSync } from "node:child_process";
     2	import { readFileSync } from "node:fs";
     3	import { describe, expect, it } from "vitest";
     4	
     5	/**
     6	 * No em dashes, anywhere that is read: docs, copy, comments, names in
     7	 * generated files. A colon, a comma, parentheses or a new sentence say the
     8	 * same thing without the tic. Binary files and the lockfile are not prose.
     9	 *
    10	 * The dash is built from its code point rather than typed, or this file
    11	 * would be the first thing it reported.
    12	 */
    13	const DASH = String.fromCharCode(0x2014);
    14	const SKIP = /\.(png|jpg|jpeg|gif|ico|woff2?|ttf|otf|streamDeckProfile|pdf|zip)$|^package-lock\.json$/;
    15	
    16	describe("em dashes", () => {
    17	  it("appear in no tracked file", () => {
    18	    const files = execFileSync("git", ["ls-files", "-z"], { encoding: "utf8" })
    19	      .split("\0")
    20	      .filter((f) => f && !SKIP.test(f));
    21	    const hits: string[] = [];
    22	    for (const file of files) {
    23	      const text = readFileSync(file, "utf8");
    24	      if (!text.includes(DASH)) continue;
    25	      text.split("\n").forEach((line, i) => {
    26	        if (line.includes(DASH)) hits.push(`${file}:${i + 1}`);
    27	      });
    28	    }
    29	    expect(hits).toEqual([]);
    30	  });
    31	});
