content.content:
  1	/**
  2	 * The profiles the plugin ships: a deck laid out before anybody touches it.
  3	 *
  4	 * Forty-four `.streamDeckProfile` files, eleven layouts across four decks.
  5	 * One is generic - the keys any run wants, whatever pack it is playing -
  6	 * and the rest are written against a pack, with its moves on keys, its
  7	 * counters and resources on the numbers, and the setups for its tool ready
  8	 * to hand out. Nothing is typed in here: the ids come out of the pack files
  9	 * through the same loader the app and the CLI use, so a renamed move
 10	 * changes the profile on the next run of this script rather than going
 11	 * quietly dead on somebody's deck.
 12	 *
 13	 * `npm run profiles -w streamdeck`. It also writes `src/profiles.ts`, which
 14	 * is the one thing here the plugin reads at run time: the table that turns a
 15	 * run's pack into the profile to switch a deck to.
 16	 *
 17	 * The container is a zip whose single top-level entry is a
 18	 * `<UUID>.sdProfile/` folder. That is not documented anywhere; it is what
 19	 * the Stream Deck app's own `DefaultProfiles` and the profiles bundled with
 20	 * Elgato's Volume Controller plugin turn out to be, and the writer below
 21	 * matches them entry for entry.
 22	 */
 23	import { createHash } from "node:crypto";
 24	import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
 25	import { basename, dirname, join } from "node:path";
 26	import { fileURLToPath } from "node:url";
 27	
 28	import { loadPackText, loadSetupText } from "@runlog/rules-schema";
 29	
 30	import { BASE, DEMO, DEVICES, DIALS, SKETCHES, SLUGS } from "./layouts.mjs";
 31	
 32	const here = dirname(fileURLToPath(import.meta.url));
 33	const plugin = join(here, "..", "com.scrthq.runlog.sdPlugin");
 34	const repo = join(here, "..", "..");
 35	
 36	/** Our own manifest, so an action's `Name` and the plugin version are never retyped. */
 37	const MANIFEST = JSON.parse(readFileSync(join(plugin, "manifest.json"), "utf8"));
 38	
 39	/** The action `Name` the app expects beside each of our UUIDs. */
 40	const NAMES = Object.fromEntries(MANIFEST.Actions.map((a) => [a.UUID, a.Name]));
 41	
 42	/** The plugin block every one of our actions carries. */
 43	const PLUGIN = { Name: MANIFEST.Name, UUID: MANIFEST.UUID, Version: MANIFEST.Version };
 44	
 45	/** What a key face looks like before the plugin draws over it. */
 46	const STATE = {
 47	  FontFamily: "",
 48	  FontSize: 12,
 49	  FontStyle: "",
 50	  FontUnderline: false,
 51	  OutlineThickness: 2,
 52	  ShowTitle: true,
 53	  TitleAlignment: "top",
 54	  TitleColor: "#ffffff",
 55	};
 56	
 57	/** The app's own page turns, which are not ours and take none of our furniture. */
 58	const PAGE_PLUGIN = { Name: "Pages", UUID: "com.elgato.streamdeck.page", Version: "1.0" };
 59	const TURNS = {
 60	  next: { Name: "Next Page", UUID: "com.elgato.streamdeck.page.next" },
 61	  previous: { Name: "Previous Page", UUID: "com.elgato.streamdeck.page.previous" },
 62	};
 63	
 64	/**
 65	 * Stable ids, so regenerating a profile is not a diff.
 66	 *
 67	 * A profile folder, its pages and every action on them want a UUID, and the
 68	 * app does not care where they came from as long as they are unique. Random
 69	 * ones would rewrite all twelve files on every run and bury a real change in
 70	 * the churn, so each is derived from what it is - the same name in, the same
 71	 * UUID out. Version 5 in shape, off a namespace of our own.
 72	 */
 73	const NAMESPACE = createHash("sha1").update("com.scrthq.runlog.profiles").digest().subarray(0, 16);
 74	
 75	export function stableId(name) {
 76	  const h = createHash("sha1").update(NAMESPACE).update(name, "utf8").digest();
 77	  h[6] = (h[6] & 0x0f) | 0x50;
 78	  h[8] = (h[8] & 0x3f) | 0x80;
 79	  const s = h.subarray(0, 16).toString("hex");
 80	  return `${s.slice(0, 8)}-${s.slice(8, 12)}-${s.slice(12, 16)}-${s.slice(16, 20)}-${s.slice(20, 32)}`;
 81	}
 82	
 83	/**
 84	 * One key, as the app stores it.
 85	 *
 86	 * `LinkedTitle` true is what lets the plugin's own title survive a copy of
 87	 * the key to another slot, and `State: 0` with a single `States` entry is
 88	 * every one of our actions: none of them has a second state.
 89	 */
 90	function entry(id, spec) {
 91	  const uuid = `${MANIFEST.UUID}.${spec.action}`;
 92	  return {
 93	    ActionID: id,
 94	    LinkedTitle: true,
 95	    Name: NAMES[uuid],
 96	    Plugin: PLUGIN,
 97	    Resources: null,
 98	    Settings: spec.settings ?? {},
 99	    State: 0,
100	    States: [STATE],
101	    UUID: uuid,
102	  };
103	}
104	
105	/** A page turn, which carries the app's plugin block and an empty face. */
106	function turn(id, which) {
107	  return {
108	    ActionID: id,
109	    LinkedTitle: true,
110	    Name: TURNS[which].Name,
111	    Plugin: PAGE_PLUGIN,
112	    Resources: null,
113	    Settings: {},
114	    State: 0,
115	    States: [{}],
116	    UUID: TURNS[which].UUID,
117	  };
118	}
119	
120	/**
121	 * The keys a pack adds to the generic fourteen.
122	 *
123	 * Its moves first, because those are what somebody presses; then the
124	 * numbers it keeps; then the setups for whatever tool it is driven by.
125	 *
126	 * A hidden counter is left out. `packages/engine/src/snapshot.ts` does not
127	 * publish one, so a key set to it would say nothing for ever - and hidden
128	 * is the pack saying it is bookkeeping rather than a number to watch.
129	 *
130	 * The setups are the tool's, not the pack's: a setup names a tool and no
131	 * pack at all, which is `forTool` in `apps/web/src/control/setups.ts`, and
132	 * they are ordered by title the way the app's own picker orders them. A
133	 * pack with no shipped control profile names no tool and gets none.
134	 *
135	 * Last, a key that opens the pack's rules in the browser: a pack profile
136	 * is the one place that key has a pack to open.
137	 */
138	export function packKeys(pack, setups) {
139	  const keys = [];
140	  for (const id of Object.keys(pack.moves ?? {})) keys.push({ action: "press", settings: { target: { kind: "move", id } } });
141	  for (const [id, counter] of Object.entries(pack.counters ?? {})) {
142	    if (!counter.hidden) keys.push({ action: "metric", settings: { field: { counter: id } } });
143	  }
144	  for (const id of Object.keys(pack.resources ?? {})) keys.push({ action: "metric", settings: { field: { resource: id } } });
145	  for (const setup of setups) keys.push({ action: "setup", settings: { setup: { id: setup.id, title: setup.title } } });
146	  keys.push({ action: "open", settings: { target: "rules" } });
147	  return keys;
148	}
149	
150	/**
151	 * The keys cut into pages, with room kept for the turns.
152	 *
153	 * Every page after the first spends its first position on a way back, and
154	 * every page with more behind it spends its last on a way on. The last page
155	 * spends neither, so a layout that fits exactly does not grow a turn key
156	 * pointing at nothing.
157	 */
158	export function paginate(keys, capacity) {
159	  const pages = [];
160	  let i = 0;
161	  while (i < keys.length) {
162	    const back = pages.length > 0 ? 1 : 0;
163	    let room = capacity - back;
164	    const more = keys.length - i > room;
165	    if (more) room -= 1;
166	    pages.push({ back: back === 1, more, keys: keys.slice(i, i + room) });
167	    i += room;
168	  }
169	  return pages;
170	}
171	
172	/** Row-major: the app names a position column first, and the top-left one is `0,0`. */
173	const at = (slot, columns) => `${slot % columns},${Math.floor(slot / columns)}`;
174	
175	/**
176	 * One profile, as a set of files, before anything is zipped.
177	 *
178	 * `ids` is handed in so a test can run the whole thing on a counter and
179	 * compare what came out; the default derives them from the profile's own
180	 * name and is what the committed files are built with.
181	 */
182	export function profile({ slug, device, name, keys }, ids = stableId) {
183	  const { model, columns, rows, dials } = DEVICES[device];
184	  const capacity = columns * rows;
185	  const cut = paginate(keys, capacity);
186	
187	  const files = {};
188	  const pageIds = [];
189	  for (const [index, page] of cut.entries()) {
190	    const id = ids(`${slug}/${device}/page/${index}`).toUpperCase();
191	    pageIds.push(id);
192	
193	    const actions = {};
194	    if (page.back) actions[at(0, columns)] = turn(ids(`${slug}/${device}/page/${index}/back`), "previous");
195	    for (const [n, key] of page.keys.entries()) {
196	      const slot = (page.back ? 1 : 0) + n;
197	      actions[at(slot, columns)] = entry(ids(`${slug}/${device}/page/${index}/key/${n}`), key);
198	    }
199	    if (page.more) actions[at(capacity - 1, columns)] = turn(ids(`${slug}/${device}/page/${index}/more`), "next");
200	
201	    const controllers = [{ Type: "Keypad", Actions: actions }];
202	    if (dials > 0) {
203	      const wheel = {};
204	      for (const [n, dial] of DIALS.slice(0, dials).entries()) {
205	        wheel[`${n},0`] = entry(ids(`${slug}/${device}/page/${index}/dial/${n}`), dial);
206	      }
207	      controllers.push({ Type: "Encoder", Actions: wheel });
208	    }
209	    files[`Profiles/${id}/manifest.json`] = { Controllers: controllers, Icon: "", Name: "" };
210	  }
211	
212	  // The default page is the empty one the app falls back to. It is not in
213	  // `Pages`, which is why a profile with one page still lists two folders.
214	  const empty = ids(`${slug}/${device}/default`).toUpperCase();
215	  files[`Profiles/${empty}/manifest.json`] = { Controllers: [{ Actions: null, Type: "Keypad" }], Icon: "", Name: "" };
216	
217	  files["manifest.json"] = {
218	    // Empty, and it has to be: the serial that sits here in a profile the
219	    // app wrote is one particular deck on one particular desk, and a
220	    // profile we ship goes to everybody's.
221	    Device: { Model: model, UUID: "" },
222	    Name: name,
223	    Pages: {
224	      Current: pageIds[0].toLowerCase(),
225	      Default: empty.toLowerCase(),
226	      Pages: pageIds.map((id) => id.toLowerCase()),
227	    },
228	    Version: "3.0",
229	  };
230	
231	  return { folder: `${ids(`${slug}/${device}`).toUpperCase()}.sdProfile`, files };
232	}
233	
234	/* -------------------------------------------------------------------- */
235	/* The container                                                         */
236	/* -------------------------------------------------------------------- */
237	
238	const CRC = (() => {
239	  const table = new Int32Array(256);
240	  for (let n = 0; n < 256; n++) {
241	    let c = n;
242	    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
243	    table[n] = c;
244	  }
245	  return table;
246	})();
247	
248	function crc32(buf) {
249	  let c = ~0;
250	  for (const b of buf) c = CRC[(c ^ b) & 0xff] ^ (c >>> 8);
251	  return ~c >>> 0;
252	}
253	
254	/**
255	 * A stored-only zip, written here rather than pulled in.
256	 *
257	 * Nothing in the repository zips anything else, and the alternative is a
258	 * dependency for two hundred lines of header. Stored rather than deflated
259	 * because a profile is a few kilobytes of JSON and the app reads either;
260	 * every timestamp is the same fixed one, so running this twice produces the
261	 * same bytes twice and the committed files only move when a layout does.
262	 */
263	export function zip(entries) {
264	  const DOS_DATE = 33; // 1980-01-01, the earliest a zip can say.
265	  const local = [];
266	  const central = [];
267	  let offset = 0;
268	  for (const { name, data } of entries) {
269	    const label = Buffer.from(name, "utf8");
270	    const body = data ?? Buffer.alloc(0);
271	    const sum = crc32(body);
272	
273	    const head = Buffer.alloc(30);
274	    head.writeUInt32LE(0x04034b50, 0);
275	    head.writeUInt16LE(20, 4);
276	    head.writeUInt16LE(0, 6);
