320	
321	/** A built profile as the bytes of a `.streamDeckProfile`, folders and all. */
322	export function container({ folder, files }) {
323	  const entries = [{ name: `${folder}/` }];
324	  const folders = new Set();
325	  for (const path of Object.keys(files)) {
326	    const parts = path.split("/").slice(0, -1);
327	    for (let i = 1; i <= parts.length; i++) folders.add(parts.slice(0, i).join("/"));
328	  }
329	  for (const dir of [...folders].sort()) entries.push({ name: `${folder}/${dir}/` });
330	  for (const [path, body] of Object.entries(files)) {
331	    entries.push({ name: `${folder}/${path}`, data: Buffer.from(JSON.stringify(body), "utf8") });
332	  }
333	  return zip(entries);
334	}
335	
336	/* -------------------------------------------------------------------- */
337	/* What goes in them                                                     */
338	/* -------------------------------------------------------------------- */
339	
340	/** The tool a pack is driven by, from the shipped control profile written for it. */
341	function toolFor(packId) {
342	  const dir = join(repo, "packs", "profiles");
343	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".json"))) {
344	    // Read as JSON rather than through the app's reader: that one wants the
345	    // tool's operation catalog to say anything useful, and all this needs is
346	    // two fields that `apps/web/src/control/shipped.test.ts` already holds
347	    // every one of these files to.
348	    const profile = JSON.parse(readFileSync(join(dir, file), "utf8"));
349	    if (profile.pack === packId) return profile.tool;
350	  }
351	  return undefined;
352	}
353	
354	/** Every setup written for a tool, by title, the way the app's picker lists them. */
355	function setupsFor(tool) {
356	  if (!tool) return [];
357	  const dir = join(repo, "packs", "setups");
358	  const out = [];
359	  for (const file of readdirSync(dir).filter((f) => f.endsWith(".yaml"))) {
360	    const parsed = loadSetupText(readFileSync(join(dir, file), "utf8"), "yaml");
361	    if (parsed.ok && parsed.setup.tool.toLowerCase() === tool.toLowerCase()) out.push(parsed.setup);
362	  }
363	  return out.sort((a, b) => a.title.localeCompare(b.title));
364	}
365	
366	/**
367	 * The layouts, in the order the manifest lists them: generic, demo, sketches.
368	 *
369	 * Every pack that ships gets one. Forty profiles auto-installing on a deck
370	 * would be forty entries in somebody's profile list on the day they install
371	 * the plugin, so a pack's four wait in the package and the plugin asks for
372	 * the one it needs; `main` writes the table it asks through.
373	 *
374	 * A sketch that no longer parses is left out rather than throwing. It is a
375	 * file in the repository with its own tests, and a broken one should fail
376	 * there rather than stop every other profile being written.
377	 */
378	export function layouts() {
379	  const sketches = readdirSync(join(repo, SKETCHES))
380	    .filter((f) => f.endsWith(".yaml"))
381	    .sort()
382	    .map((f) => ({ slug: SLUGS[basename(f, ".yaml")] ?? basename(f, ".yaml"), file: `${SKETCHES}/${f}` }));
383	
384	  const out = [{ slug: "runlog", name: "Runlog", pack: null }];
385	  for (const { slug, file } of [DEMO, ...sketches]) {
386	    const parsed = loadPackText(readFileSync(join(repo, file), "utf8"), "yaml");
387	    if (!parsed.ok) continue;
388	    // The pack's own title, and nothing else: the Stream Deck app already
389	    // says which plugin a profile came with.
390	    out.push({ slug, name: parsed.pack.title, pack: parsed.pack });
391	  }
392	  return out;
393	}
394	
395	/** The forty-four profiles, named and keyed, ready to be laid out on a grid. */
396	export function specs() {
397	  const out = [];
398	  for (const layout of layouts()) {
399	    const keys = layout.pack ? [...BASE, ...packKeys(layout.pack, setupsFor(toolFor(layout.pack.id)))] : BASE;
400	    for (const device of Object.keys(DEVICES)) out.push({ slug: layout.slug, device, name: layout.name, keys });
401	  }
402	  return out;
403	}
404	
405	/**
406	 * The table the plugin switches through, as a module it can import.
407	 *
408	 * The plugin never spells a profile name out. A pack renamed here, or a
409	 * sketch added to the repository, moves this file on the next run of the
410	 * generator, and the two stay one thing rather than two lists that drift.
411	 */
412	export function table(list = layouts()) {
413	  const packs = list.filter((l) => l.pack).map((l) => `  "${l.pack.id}": "${l.slug}",`);
414	  const decks = Object.entries(DEVICES).map(([device, { type }]) => `  ${type}: "${device}",`);
415	  return `/**
416	 * Which profile a run's pack is laid out in, and what each deck is called.
417	 *
418	 * Written by \`design/profiles.mjs\`: run \`npm run profiles -w streamdeck\`
419	 * and commit what moves. Editing it by hand renames a profile the plugin
420	 * asks for without renaming the file behind it, and the switch then does
421	 * nothing at all.
422	 */
423	
424	/** The slug of the profile laid out for each pack the plugin ships. */
425	export const PACK_PROFILES: Record<string, string> = {
426	${packs.join("\n")}
427	};
428	
429	/** What a profile name calls each deck, by the SDK's \`DeviceType\`. */
430	export const DEVICE_PROFILES: Record<number, string> = {
431	${decks.join("\n")}
432	};
433	
434	/** The layout a run gets where its pack ships none, which is every Marketplace pack. */
435	export const GENERIC_PROFILE = "runlog";
436	
437	/**
438	 * The profile to put a deck on for a run of this pack.
439	 *
440	 * \`null\` for a deck nothing here is laid out for - a Pedal, a Neo - which is
441	 * a deck to leave alone rather than one to push the generic layout onto.
442	 */
443	export function profileFor(packId: string | undefined, device: number): string | null {
444	  const deck = DEVICE_PROFILES[device];
445	  if (deck === undefined) return null;
446	  const slug = (packId === undefined ? undefined : PACK_PROFILES[packId]) ?? GENERIC_PROFILE;
447	  return \`profiles/\${slug}-\${deck}\`;
448	}
449	`;
450	}
451	
452	function main() {
453	  const dir = join(plugin, "profiles");
454	  mkdirSync(dir, { recursive: true });
455	
456	  const written = [];
457	  for (const spec of specs()) {
458	    const file = `${spec.slug}-${spec.device}`;
459	    writeFileSync(join(dir, `${file}.streamDeckProfile`), container(profile(spec)));
460	    // The generic four come with the plugin; a pack's four are installed the
461	    // first time a deck follows a run of that pack.
462	    written.push({ name: `profiles/${file}`, type: DEVICES[spec.device].type, auto: spec.slug === "runlog" });
463	  }
464	
465	  writeFileSync(join(here, "..", "src", "profiles.ts"), table());
466	
467	  // The manifest is edited by hand - a generator that rewrites it fights the
468	  // formatter over every other line - so the one thing checked here is that
469	  // it still lists what was just written, in the same order.
470	  const listed = (MANIFEST.Profiles ?? []).map((p) => `${p.Name}:${p.DeviceType}:${p.AutoInstall}`).join(" ");
471	  const expected = written.map((p) => `${p.name}:${p.type}:${p.auto}`).join(" ");
472	  if (listed !== expected) throw new Error(`manifest.json lists\n  ${listed}\nbut this wrote\n  ${expected}`);
473	
474	  console.log(`${written.length} profiles written to ${dir}`);
475	}
476	
477	if (process.argv[1] === fileURLToPath(import.meta.url)) main();

