$root = Join-Path $env:TEMP "sdreview\out\C0B720C8-F67D-5AE7-AF4F-68D7B5703C62.sdProfile"
Get-Content (Join-Path $root "manifest.json")
"--- pages ---"
Get-ChildItem (Join-Path $root "Profiles") | ForEach-Object {
  $m = Get-Content (Join-Path $_.FullName "manifest.json") -Raw | ConvertFrom-Json
  $keypad = $m.Controllers | Where-Object { $_.Type -eq "Keypad" }
  $enc = $m.Controllers | Where-Object { $_.Type -eq "Encoder" }
  $kn = if ($keypad.Actions) { ($keypad.Actions.PSObject.Properties | Measure-Object).Count } else { 0 }
  $en = if ($enc -and $enc.Actions) { ($enc.Actions.PSObject.Properties | Measure-Object).Count } else { 0 }
  "$($_.Name)  keypad=$kn encoder=$en  slots=$(if($keypad.Actions){($keypad.Actions.PSObject.Properties.Name) -join ' '})"
}

