     1	/**
     2	 * The account block every inspector carries: the address, sign in, sign out,
     3	 * reconnect, and the device flow's code while one is running.
     4	 *
     5	 * A script rather than an HTML fragment because a property inspector page is
     6	 * loaded straight from disk with no build step and no include - so the block
     7	 * has one home here and each page is one line.
     8	 *
     9	 * Drop `<div id="runlog-account"></div>` on the page, then load this after
    10	 * sdpi-components.js.
    11	 *
    12	 * That script sits beside this one - sdpi-components v4.0.1, downloaded
    13	 * from https://sdpi-components.dev/releases/v4/sdpi-components.js and
    14	 * shipped in the plugin, because an inspector that fetches its own
    15	 * components off the internet has no sign-in button when the internet is
    16	 * not there. Replace it by downloading the next release over it.
    17	 */
    18	(() => {
    19	  const mount = document.getElementById("runlog-account");
    20	  if (!mount) return;
    21	  const { streamDeckClient } = SDPIComponents;
    22	
    23	  mount.innerHTML = `
    24	    <sdpi-item label="Runlog address">
    25	      <sdpi-textfield setting="apiBase" global placeholder="https://runlog.scrthq.com"></sdpi-textfield>
    26	    </sdpi-item>
    27	    <sdpi-item label="Account">
    28	      <sdpi-button id="runlog-signin">Sign in</sdpi-button>
    29	      <sdpi-button id="runlog-signout">Sign out</sdpi-button>
    30	      <sdpi-button id="runlog-reconnect">Reconnect</sdpi-button>
    31	    </sdpi-item>
    32	    <sdpi-item label="Status"><span id="runlog-who">Loading…</span></sdpi-item>
    33	    <div id="runlog-code-row" style="display: none">
    34	      <sdpi-item label="Your code">
    35	        <strong id="runlog-code"></strong>
    36	        <a id="runlog-link" target="_blank" rel="noreferrer">Open the sign-in page</a>
    37	      </sdpi-item>
    38	    </div>`;
    39	
    40	  const el = (id) => document.getElementById(id);
    41	  const send = (payload) => streamDeckClient.send("sendToPlugin", payload);
    42	
    43	  el("runlog-signin").addEventListener("click", () => {
    44	    el("runlog-who").textContent = "Signing in…";
    45	    send({ t: "signin" });
    46	  });
    47	  el("runlog-signout").addEventListener("click", () => send({ t: "signout" }));
    48	  el("runlog-reconnect").addEventListener("click", () => send({ t: "reconnect" }));
    49	
    50	  streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
    51	    if (!payload) return;
    52	    if (payload.t === "code") {
    53	      el("runlog-code-row").style.display = "";
    54	      el("runlog-code").textContent = payload.code;
    55	      // The link comes off a socket; only an http(s) one is worth opening.
    56	      el("runlog-link").href = /^https?:\/\//.test(payload.url ?? "") ? payload.url : "";
    57	    }
    58	    if (payload.t === "who") {
    59	      el("runlog-code-row").style.display = "none";
    60	      const signedIn = payload.signedIn ? "Signed in" : "Not signed in";
    61	      // A sign-in that failed says why, and keeps saying it until the next
    62	      // time the plugin reports who is signed in.
    63	      el("runlog-who").textContent = payload.error ? `${signedIn}: ${payload.error}` : signedIn;
    64	    }
    65	  });
    66	})();
=== metric.html ===
     1	<!doctype html>
     2	<html>
     3	  <head lang="en">
     4	    <title>Metric Settings</title>
     5	    <meta charset="utf-8" />
     6	    <script src="sdpi-components.js"></script>
     7	    <style>
     8	      /* The press rows are only for a counter or a resource, and a custom
     9	         element can style its way out of the browser's own `hidden`. */
    10	      [hidden] {
    11	        display: none !important;
    12	      }
    13	    </style>
    14	  </head>
    15	
    16	  <body>
    17	    <sdpi-item label="Show">
    18	      <select id="field"></select>
    19	    </sdpi-item>
    20	
    21	    <sdpi-item id="press-item" label="On press" hidden>
    22	      <select id="press">
    23	        <option value="step">+1</option>
    24	        <option value="set">Set to</option>
    25	      </select>
    26	    </sdpi-item>
    27	
    28	    <sdpi-item id="value-item" label="Set to" hidden>
    29	      <input id="value" type="number" step="1" />
    30	    </sdpi-item>
    31	
    32	    <div id="runlog-account"></div>
    33	    <script src="account.js"></script>
    34	    <script>
    35	      // Five fields every pack has, then whatever counters and resources the
    36	      // attached run is keeping - those come from the plugin on every appear.
    37	      // A counter or a resource is a key as well as a number, so those two
    38	      // are the only fields the press rows are offered for.
    39	      (() => {
    40	        const { streamDeckClient } = SDPIComponents;
    41	        const field = document.getElementById("field");
    42	        const press = document.getElementById("press");
    43	        const value = document.getElementById("value");
    44	        const pressItem = document.getElementById("press-item");
    45	        const valueItem = document.getElementById("value-item");
    46	        const FIXED = [
    47	          ["score", "Score"],
    48	          ["unit", "Unit"],
    49	          ["clock", "Clock"],
    50	          ["latest", "Last result"],
    51	          ["leader", "Leader"],
    52	        ];
    53	        let current = null;
    54	        let onPress = { kind: "step" };
    55	
    56	        const option = (value, label) => {
    57	          const o = document.createElement("option");
    58	          o.value = JSON.stringify(value);
    59	          o.textContent = label;
    60	          return o;
    61	        };
    62	
    63	        const fill = (counters, resources) => {
    64	          field.replaceChildren(option(null, "Set up"), ...FIXED.map(([v, l]) => option(v, l)));
    65	          for (const c of counters) field.appendChild(option({ counter: c.id }, c.label));
    66	          for (const r of resources) field.appendChild(option({ resource: r.id }, r.label));
    67	          show();
    68	        };
    69	
    70	        const show = () => {
    71	          const chosen = JSON.stringify(current ?? null);
    72	          const match = [...field.options].find((o) => o.value === chosen);
    73	          if (match) field.value = match.value;
    74	          // The fixed fields are the run's own arithmetic and take no press.
    75	          const adjustable = current !== null && typeof current === "object";
    76	          pressItem.hidden = !adjustable;
    77	          valueItem.hidden = !adjustable || onPress.kind !== "set";
    78	          press.value = onPress.kind;
    79	          value.value = onPress.kind === "set" ? String(onPress.value) : "";
    80	        };
    81	
    82	        const save = () => {
    83	          streamDeckClient.setSettings(current ? { field: current, press: onPress } : {});
    84	          show();
    85	        };
    86	
    87	        field.addEventListener("change", () => {
    88	          current = JSON.parse(field.value);
    89	          save();
    90	        });
    91	        press.addEventListener("change", () => {
    92	          onPress = press.value === "set" ? { kind: "set", value: Number(value.value) || 0 } : { kind: "step" };
    93	          save();
    94	        });
    95	        value.addEventListener("change", () => {
    96	          onPress = { kind: "set", value: Number(value.value) || 0 };
    97	          save();
    98	        });
    99	
   100	        streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
   101	          if (payload?.t === "fields") fill(payload.counters ?? [], payload.resources ?? []);
   102	        });
   103	        void streamDeckClient.getSettings().then(({ settings }) => {
   104	          current = settings?.field ?? null;
   105	          onPress = settings?.press ?? { kind: "step" };
   106	          show();
   107	        });
   108	        fill([], []);
   109	      })();
   110	    </script>
   111	  </body>
   112	</html>

