  1	import { readFileSync, readdirSync } from "node:fs";
  2	import { dirname, join } from "node:path";
  3	import { fileURLToPath } from "node:url";
  4	import { describe, expect, it } from "vitest";
  5	import { loadPackText, loadSetupText } from "@runlog/rules-schema";
  6	
  7	import { DEVICES, SKETCHES, SLUGS } from "./layouts.mjs";
  8	import { container, layouts, profile, specs, table } from "./profiles.mjs";
  9	
 10	/**
 11	 * The profiles the plugin ships, held against the packs they were written
 12	 * from and the grids they have to fit on.
 13	 *
 14	 * Nobody reads a `.streamDeckProfile`. It is a zip of compact JSON that goes
 15	 * out with a release and turns up on somebody's desk, and the two ways it
 16	 * goes wrong - a key off the edge of a Mini, a move whose id the pack
 17	 * renamed last month - both look, to whoever imported it, like the plugin
 18	 * being broken. So the generator is held to the grid and to the pack here,
 19	 * where a mistake costs a test run rather than a support thread.
 20	 */
 21	
 22	const here = dirname(fileURLToPath(import.meta.url));
 23	const plugin = join(here, "..", "com.scrthq.runlog.sdPlugin");
 24	const repo = join(here, "..", "..");
 25	
 26	const MANIFEST = JSON.parse(readFileSync(join(plugin, "manifest.json"), "utf8"));
 27	
 28	/** Everything a key on one of these may be: our twelve actions, and the app's two turns. */
 29	const ALLOWED = new Set([...MANIFEST.Actions.map((a) => a.UUID), "com.elgato.streamdeck.page.next", "com.elgato.streamdeck.page.previous"]);
 30	
 31	/** Every action on every page of a built profile, with the page and position it sits at. */
 32	function placed(built) {
 33	  const out = [];
 34	  for (const [path, page] of Object.entries(built.files)) {
 35	    if (!page.Controllers) continue;
 36	    for (const controller of page.Controllers) {
 37	      for (const [position, action] of Object.entries(controller.Actions ?? {})) {
 38	        out.push({ page: path, controller: controller.Type, position, action });
 39	      }
 40	    }
 41	  }
 42	  return out;
 43	}
 44	
 45	const all = specs().map((spec) => ({ spec, built: profile(spec) }));
 46	
 47	describe("the profiles we ship", () => {
 48	  it("lays one out for the generic keys and one for every pack that ships", () => {
 49	    // The demo pack and every sketch, by the slug each takes from its file
 50	    // name. Written out rather than read from the folder a second time: this
 51	    // is the list, and a sketch that stopped parsing would otherwise drop
 52	    // off it without a word.
 53	    expect(layouts().map((l) => l.slug)).toEqual([
 54	      "runlog",
 55	      "demo",
 56	      "elden-ring",
 57	      "forfeits",
 58	      "ladder-work",
 59	      "practice-room",
 60	      "rocket-league-ladder",
 61	      "rocket-league-showdown",
 62	      "run-of-show",
 63	      "soundclash",
 64	      "twenty-five",
 65	    ]);
 66	    const sketches = readdirSync(join(repo, SKETCHES)).filter((f) => f.endsWith(".yaml"));
 67	    expect(layouts()).toHaveLength(sketches.length + 2);
 68	    expect(all).toHaveLength(layouts().length * Object.keys(DEVICES).length);
 69	    expect(all).toHaveLength(44);
 70	  });
 71	
 72	  it("is one per pack per device, and the manifest lists every one", () => {
 73	    expect(all.map(({ spec }) => `${spec.slug}-${spec.device}`)).toEqual(MANIFEST.Profiles.map((p) => p.Name.replace("profiles/", "")));
 74	    for (const p of MANIFEST.Profiles) {
 75	      const device = p.Name.split("-").pop();
 76	      expect(p.DeviceType, `${p.Name} should be laid out for the device it names`).toBe(DEVICES[device].type);
 77	    }
 78	  });
 79	
 80	  it("installs the generic four with the plugin and a pack's four on demand", () => {
 81	    // Forty profiles arriving on the day somebody installs the plugin is a
 82	    // profile list nobody can find their own work in. A pack's four are
 83	    // installed the first time a deck follows a run of that pack, and never
 84	    // switch themselves on the way in: the plugin says when.
 85	    for (const p of MANIFEST.Profiles) {
 86	      const generic = p.Name.startsWith("profiles/runlog-");
 87	      expect(p.AutoInstall, `${p.Name}`).toBe(generic);
 88	      expect(p.DontAutoSwitchWhenInstalled, `${p.Name}`).toBe(true);
 89	    }
 90	    expect(MANIFEST.Profiles.filter((p) => p.AutoInstall)).toHaveLength(4);
 91	  });
 92	
 93	  it("hands the plugin a table of the names rather than letting it guess them", () => {
 94	    // `src/profiles.ts` is written by the generator and read at run time. If
 95	    // it is behind the packs on disk the plugin asks for a profile that is
 96	    // not in the package, and the switch does nothing anybody can see.
 97	    const written = readFileSync(join(here, "..", "src", "profiles.ts"), "utf8");
 98	    expect(written.replace(/\r\n/g, "\n")).toBe(table().replace(/\r\n/g, "\n"));
 99	    for (const layout of layouts()) {
100	      if (layout.pack) expect(written).toContain(`"${layout.pack.id}": "${layout.slug}"`);
101	    }
102	  });
103	
104	  it("keeps the slug Elden Ring's profile shipped under", () => {
105	    // Its file name says the tool as well as the game; its slug does not,
106	    // and changing that now would rename the profile on every deck that
107	    // already has it.
108	    expect(SLUGS["elden-ring-tarnishedtool"]).toBe("elden-ring");
109	    expect(layouts().find((l) => l.slug === "elden-ring").pack.id).toBe("com.scrthq.runlog.elden-ring-tarnishedtool");
110	  });
111	
112	  it("builds the same bytes twice, so regenerating is not a diff", () => {
113	    for (const { spec } of all) {
114	      expect(container(profile(spec)).equals(container(profile(spec))), `${spec.slug}-${spec.device}`).toBe(true);
115	    }
116	  });
117	
118	  it("knows how big each deck is", () => {
119	    // Written out rather than taken from `DEVICES`, which is the table under
120	    // test: the grid check below reads the same numbers the layout was built
121	    // from, so without this it would pass on any pair of them. These are the
122	    // SDK's, from the `DeviceType` enumeration in @elgato/schemas.
123	    expect(DEVICES.xl).toMatchObject({ type: 2, columns: 8, rows: 4, dials: 0 });
124	    expect(DEVICES.sd).toMatchObject({ type: 0, columns: 5, rows: 3, dials: 0 });
125	    expect(DEVICES.mini).toMatchObject({ type: 1, columns: 3, rows: 2, dials: 0 });
126	    expect(DEVICES.plus).toMatchObject({ type: 7, columns: 4, rows: 2, dials: 4 });
127	  });
128	
129	  it("lays every key inside its own deck's grid", () => {
130	    for (const { spec, built } of all) {
131	      const { columns, rows, dials } = DEVICES[spec.device];
132	      for (const { controller, position } of placed(built)) {
133	        const [column, row] = position.split(",").map(Number);
134	        const width = controller === "Encoder" ? dials : columns;
135	        const height = controller === "Encoder" ? 1 : rows;
136	        expect(column, `${spec.slug}-${spec.device} ${position}`).toBeLessThan(width);
137	        expect(row, `${spec.slug}-${spec.device} ${position}`).toBeLessThan(height);
138	        expect(column).toBeGreaterThanOrEqual(0);
139	        expect(row).toBeGreaterThanOrEqual(0);
140	      }
141	    }
142	  });
143	
144	  it("puts one thing in one place", () => {
145	    for (const { spec, built } of all) {
146	      const seen = new Set();
147	      for (const { page, controller, position } of placed(built)) {
148	        const where = `${page} ${controller} ${position}`;
149	        expect(seen.has(where), `${spec.slug}-${spec.device} doubles up on ${where}`).toBe(false);
150	        seen.add(where);
151	      }
152	    }
153	  });
154	
155	  it("places nothing but our own actions and the app's page turns", () => {
156	    for (const { spec, built } of all) {
157	      for (const { action } of placed(built)) {
158	        expect(ALLOWED.has(action.UUID), `${spec.slug}-${spec.device} places ${action.UUID}`).toBe(true);
159	      }
160	    }
161	  });
162	
163	  it("sets each key to what its own settings type allows", () => {
164	    // The shapes are `PressTarget`, `MetricField`, `SetupSettings` and
165	    // `NextSettings` in `src/state.ts`. A key set to something the plugin
166	    // cannot read draws "Set up" for ever and says nothing about why.
167	    const fields = new Set(["score", "unit", "clock", "latest", "leader"]);
168	    const kinds = new Set(["roll", "move", "answer"]);
169	    for (const { spec, built } of all) {
170	      for (const { action } of placed(built)) {
171	        const settings = action.Settings;
172	        const where = `${spec.slug}-${spec.device} ${action.UUID}`;
173	        if (action.UUID === "com.scrthq.runlog.metric") {
174	          const field = settings.field;
175	          if (typeof field === "string") expect(fields.has(field), where).toBe(true);
176	          else expect(Object.keys(field), where).toSatisfy((keys) => keys.length === 1 && ["counter", "resource"].includes(keys[0]));
177	        } else if (action.UUID === "com.scrthq.runlog.press") {
178	          expect(kinds.has(settings.target.kind), where).toBe(true);
179	          if (settings.target.kind === "move") expect(typeof settings.target.id, where).toBe("string");
180	        } else if (action.UUID === "com.scrthq.runlog.setup") {
181	          expect(Object.keys(settings.setup).sort(), where).toEqual(["id", "title"]);
182	        } else if (action.UUID === "com.scrthq.runlog.open") {
183	          expect(["run", "guide", "rules", "newrun", "dock"], where).toContain(settings.target);
184	        } else {
185	          expect(settings, where).toEqual({});
186	        }
187	      }
188	    }
189	  });
190	
191	  it("gives a + its dials, and no other deck one", () => {
192	    for (const { spec, built } of all) {
193	      const wheels = placed(built).filter((p) => p.controller === "Encoder");
194	      if (spec.device !== "plus") {
195	        expect(wheels, `${spec.slug}-${spec.device}`).toHaveLength(0);
196	        continue;
197	      }
198	      // Only Next and Metric declare `Encoder` in the manifest.
199	      for (const { action } of wheels) {
200	        expect(["com.scrthq.runlog.next", "com.scrthq.runlog.metric"]).toContain(action.UUID);
201	      }
202	    }
203	  });
204	
205	  describe("the Elden Ring profile", () => {
206	    const pack = loadPackText(readFileSync(join(repo, "packs", "sketches", "elden-ring-tarnishedtool.yaml"), "utf8"), "yaml");
207	    const tool = JSON.parse(readFileSync(join(repo, "packs", "profiles", "elden-ring-tarnishedtool.json"), "utf8")).tool;
208	    const setups = ["bare-handed", "brute", "cleric", "glass", "long-night", "sorcerer", "well-armed"];
209	
210	    it("loads the pack it is built from", () => {
211	      expect(pack.ok).toBe(true);
212	    });
213	
214	    for (const device of Object.keys(DEVICES)) {
215	      it(`carries exactly the pack's moves, counters, resources and setups on a ${device}`, () => {
216	        const built = all.find(({ spec }) => spec.slug === "elden-ring" && spec.device === device).built;
217	        const settings = placed(built).map((p) => p.action.Settings);
218	
219	        const moves = settings.filter((s) => s.target?.kind === "move").map((s) => s.target.id);
220	        expect(moves.sort()).toEqual(Object.keys(pack.pack.moves).sort());
221	
222	        const counters = settings.filter((s) => typeof s.field === "object" && "counter" in s.field).map((s) => s.field.counter);
223	        const shown = Object.entries(pack.pack.counters)
224	          .filter(([, c]) => !c.hidden)
225	          .map(([id]) => id);
226	        expect(counters.sort()).toEqual(shown.sort());
227	
228	        const resources = settings.filter((s) => typeof s.field === "object" && "resource" in s.field).map((s) => s.field.resource);
229	        expect(resources.sort()).toEqual(Object.keys(pack.pack.resources).sort());
230	
231	        const chosen = settings.filter((s) => s.setup).map((s) => s.setup.id);
232	        expect(chosen.sort()).toEqual(shippedFor(tool).sort());
233	        // The loadouts, at least, and by id rather than by count: a setup
234	        // that stopped naming this tool would otherwise vanish unremarked.
235	        for (const id of setups) expect(chosen).toContain(`com.scrthq.runlog.setups.${id}`);
236	      });
237	    }
238	  });
239	
240	  it("gives every profile the run and the guide, and only a pack's the rules", () => {
241	    for (const { spec, built } of all) {
242	      const targets = placed(built)
243	        .filter((p) => p.action.UUID === "com.scrthq.runlog.open")
244	        .map((p) => p.action.Settings.target)
245	        .sort();
246	      const want = spec.slug === "runlog" ? ["guide", "run"] : ["guide", "rules", "run"];
247	      expect(targets, `${spec.slug}-${spec.device}`).toEqual(want);
248	    }
249	  });
250	
251	  it("gives the demo pack no setup keys, because it names no tool", () => {
252	    const built = all.find(({ spec }) => spec.slug === "demo" && spec.device === "xl").built;
253	    expect(placed(built).filter((p) => p.action.UUID === "com.scrthq.runlog.setup")).toHaveLength(0);
254	  });
255	});
