257	/** Every shipped setup written for a tool, by id. */
258	function shippedFor(tool) {
259	  const dir = join(repo, "packs", "setups");
260	  return readdirSync(dir)
261	    .filter((f) => f.endsWith(".yaml"))
262	    .map((f) => loadSetupText(readFileSync(join(dir, f), "utf8"), "yaml"))
263	    .filter((r) => r.ok && r.setup.tool.toLowerCase() === tool.toLowerCase())
264	    .map((r) => r.setup.id);
265	}

