}

// ---- the same run as numbers, for a stream plugin: the owner's snapshot, flat ----
const publicMetrics = path.match(/^\/api\/public\/runs\/([^/]+)\/metrics$/);
if (publicMetrics && method === "GET") {
  const id = decodeURIComponent(publicMetrics[1]!);
  const t = event.queryStringParameters?.["t"] ?? "";
  const found = await store.getSession(id);
  // A plugin's page is anywhere, so the answer says any origin may read it: the token is the key.
  const open = (status: number, body: unknown): Result => ({
    statusCode: status,
    headers: { "content-type": "application/json; charset=utf-8", "access-control-allow-origin": "*", "cache-control": "no-store" },
    body: JSON.stringify(body),
  });
  if (!found || !t || !found.meta.publicTokenHash || hashToken(t) !== found.meta.publicTokenHash) return open(200, { found: false });
  if (found.meta.deletedAt) return open(410, { found: false, deletedAt: found.meta.deletedAt });
  const m = found.meta;
  const snap = await store.getSnapshot(id);
  return open(200, {
    found: true,
    ...metricsOf(
      { id: m.id, packId: m.packId, packTitle: m.packTitle ?? null, name: m.name ?? null, endedAt: m.endedAt ?? null },
      snap,
      now(),
    ),
  });
}

/**
 * What a watch key may draw: this account's runs that are open to watch,
 * newest first, and which of them is in play.
 *
 * A browser source is set up once and lives in a scene for months, so
 * its address cannot name a run. It names the account, and this says
 * what there is. Which one a given source draws is that source's own
 * business, chosen at its end and remembered there, because one answer
 * here could never serve two sources pointed at two different runs.
 *
 * In play is simply the one moved most recently, which is the one being
 * played without anyone having to say so.
 */
/**
 * The numbers of the run in play, by a watch key.
 *
 * The same document the per-run metrics address answers with, reached
 * without a run id or a link's token: a `!score` command should not ask
 * anyone to pick a live link apart for the pieces inside it.
 */
const streamMetrics = path === "/api/public/stream/metrics";
if (streamMetrics && method === "GET") {
  const k = event.queryStringParameters?.["k"] ?? "";
  const open = (status: number, body: unknown): Result => ({
    statusCode: status,
    headers: { "content-type": "application/json; charset=utf-8", "access-control-allow-origin": "*", "cache-control": "no-store" },
    body: JSON.stringify(body),
  });
  const owner = k ? await store.streamKeyOwner(hashToken(k)) : null;
  if (!owner || owner.kind !== "watch") return open(200, { ok: false, say: "That is not a key for watching a run." });
  const named = (event.queryStringParameters?.["run"] ?? "").trim();
  const { sessions } = await store.manifest(owner.sub);
  const live = sessions
    .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt && (!named || p.id === named))
    .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0))
    .slice(0, STREAM_RUNS_LISTED);
  for (const p of live) {
    const found = await store.getSession(p.id);
    if (!found?.meta.publicTokenHash) continue;
    const m = found.meta;
    const snap = await store.getSnapshot(p.id);
    return open(200, {
      ok: true,
      runId: p.id,
      ...metricsOf(
        { id: m.id, packId: m.packId, packTitle: m.packTitle ?? null, name: m.name ?? null, endedAt: m.endedAt ?? null },
        snap,
        now(),
      ),
    });
  }
  return open(200, { ok: false, say: "No run is open to watch right now." });
}

